/**
 * EPL lane status — the product-state contract for the protected /launch console.
 *
 * EVERY field is DERIVED from a committed artifact on disk. Nothing is typed by hand, and a missing
 * source renders UNKNOWN — never green, never zero. "We could not read it" and "there is nothing"
 * are different facts and only one of them is a product state.
 *
 * WHY THIS EXISTS. The sport gate's `products` stage asks for boards or cards generated by
 * scheduled automation ON THE PRODUCT-STATE CONTRACT. NFL has had such an artifact since P171; EPL
 * has had none, so its product state lived only in prose in the assessments registry and in
 * whatever a reader could infer from the artifacts themselves. A state nothing publishes is a state
 * nothing can be held to.
 *
 * IT DOES NOT CREATE A PRODUCT. Declaring EPL's lane state is not the same as making EPL a live
 * paper-product lane, and this script takes no view on whether it should be — that is a founder
 * decision with money adjacency, and it is recorded here as a blocker rather than assumed away.
 *
 * INTERNAL. prune-internal-routes sweeps app/public/data by build reference, so this ships only to
 * the host-protected deployment. Nothing here is a public claim.
 *
 * Usage: npx tsx scripts/epl/build-epl-lane-status.mjs --now <iso>   (from app/ — see below)
 * Writes: app/public/data/admin/epl-lane.json
 *
 * tsx AND app/ AS CWD ARE BOTH REQUIRED: this imports graded-record.ts, which imports through the
 * "@/" alias declared in app/tsconfig.json. Guarded by lib/ops/workflow-script-cwd.test.mjs.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { SPORT_ASSESSMENTS } from "../../src/lib/sports/sport-assessments.mjs";
import { deriveSportMaturity, remainingPath, GATE_STAGES } from "../../src/lib/sports/sport-gate.mjs";
import { kickoffClusters, lineupSlotCoverage, parseCronSlots } from "../../src/lib/sports/epl/lineup-slot-coverage.mjs";
import { parseWeeklySlots, projectSeasonSpend } from "../../src/lib/sports/epl/odds-budget.mjs";
import { loadEplGradedRecord } from "../../src/lib/sports/epl/graded-record.ts";
import { labEligibility } from "../parlays/lab-eligibility.mjs";

const APP = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const ROOT = path.join(APP, "..");
const arg = (n, f = null) => { const i = process.argv.indexOf(n); return i !== -1 && process.argv[i + 1] ? process.argv[i + 1] : f; };
const NOW = arg("--now");
if (!NOW || !Number.isFinite(Date.parse(NOW))) { console.error("REFUSED: --now <ISO> required"); process.exit(1); }
const nowMs = Date.parse(NOW);

const read = (p) => { try { return JSON.parse(fs.readFileSync(p, "utf8")); } catch { return null; } };
const readText = (p) => { try { return fs.readFileSync(p, "utf8"); } catch { return null; } };
const UNKNOWN = (why) => ({ state: "UNKNOWN", detail: why });

// ── sources ─────────────────────────────────────────────────────────────────────────────────────
const fixtureCapture = (() => {
  const dir = path.join(APP, "public/data/soccer/epl/fixtures");
  try {
    const f = fs.readdirSync(dir).filter((n) => n.startsWith("capture-")).sort().pop();
    return f ? { file: f, ...read(path.join(dir, f)) } : null;
  } catch { return null; }
})();
const odds = read(path.join(APP, "public/data/soccer/epl/odds/latest.json"));
const forecasts = read(path.join(APP, "public/data/soccer/epl/forecasts/latest.json"));
const players = read(path.join(APP, "public/data/soccer/epl/player-projections/latest.json"));
const results = read(path.join(APP, "public/data/soccer/epl/results/latest.json"));
const ledger = read(path.join(ROOT, "data/internal/research/odds/epl/authorization-ledger.json"));
const receipt = readText(path.join(ROOT, "docs/receipts/ODDS_AUTHORIZATION_EPL.md"));
const workflow = readText(path.join(ROOT, ".github/workflows/epl-matchweek.yml"));

/** Age of an artifact by its OWN stamp — never a file mtime, which records when git touched it. */
const freshnessOf = (label, artifact, keys) => {
  if (!artifact) return UNKNOWN(`no ${label} artifact`);
  const stamp = keys.map((k) => artifact[k]).find((v) => typeof v === "string" && Number.isFinite(Date.parse(v)));
  if (!stamp) return UNKNOWN(`${label} carries no readable stamp`);
  return { state: "READ", stampedAt: stamp, ageHours: Number(((nowMs - Date.parse(stamp)) / 3.6e6).toFixed(2)) };
};

// ── the next kickoff cluster, and whether the cadence can serve it ───────────────────────────────
const fixtures = fixtureCapture?.rows ?? [];
const upcoming = fixtures.map((f) => ({ ...f, ms: Date.parse(f.kickoffIso) })).filter((f) => Number.isFinite(f.ms) && f.ms > nowMs).sort((a, b) => a.ms - b.ms);
const nextCluster = upcoming.length
  ? {
      kickoffUtc: new Date(upcoming[0].ms).toISOString(),
      fixtures: upcoming.filter((f) => f.ms === upcoming[0].ms).length,
      hoursAway: Number(((upcoming[0].ms - nowMs) / 3.6e6).toFixed(2)),
    }
  : UNKNOWN("no fixture ahead of the clock");

const coverage = workflow && fixtures.length
  ? (() => {
      const first = Math.min(...fixtures.map((f) => Date.parse(f.kickoffIso)).filter(Number.isFinite));
      const cl = kickoffClusters(fixtures, { fromIso: new Date(Math.max(first, nowMs)).toISOString(), toIso: new Date(nowMs + 21 * 86_400_000).toISOString() });
      const c = lineupSlotCoverage(cl, parseCronSlots(workflow));
      return { state: c.uncoveredFixtures === 0 ? "EVERY_CLUSTER_SERVED" : "GAP", clusters: c.totalClusters, covered: c.coveredClusters, uncoveredMatches: c.uncoveredFixtures, uncovered: c.uncovered };
    })()
  : UNKNOWN("no workflow or fixture list to check coverage against");

// ── credits: what has been spent, and whether the cadence can finish the season ──────────────────
const CEILING = Number(/(\d+)\s+credits/.exec(receipt ?? "")?.[1] ?? 0) || null;
const budget = ledger && workflow && fixtures.length && CEILING
  ? (() => {
      const windowH = Number(/--require-kickoff-within-hours",\s*"(\d+)"/.exec(readText(path.join(APP, "scripts/epl/capture-epl-odds.mjs")) ?? "")?.[1]);
      const p = projectSeasonSpend(fixtures, parseWeeklySlots(workflow), {
        fromIso: NOW, creditsPerCall: 2, windowHours: Number.isFinite(windowH) ? windowH : null,
        alreadySpent: ledger.cumulativeCredits ?? 0, ceiling: CEILING,
      });
      return p ? { state: p.verdict, spent: p.alreadySpent, projectedRemaining: p.projectedCredits, projectedTotal: p.projectedTotal, ceiling: p.ceiling, headroom: p.headroom, kickoffWindowHours: windowH, spendingFirings: p.spendingFirings, skippedFirings: p.skippedFirings } : UNKNOWN("projection produced nothing");
    })()
  : UNKNOWN("no ledger, receipt, workflow or fixture list — spend cannot be projected");

// ── the gate ────────────────────────────────────────────────────────────────────────────────────
const stages = SPORT_ASSESSMENTS.epl.stages;
const maturity = deriveSportMaturity(stages, SPORT_ASSESSMENTS.epl);
const proven = GATE_STAGES.filter((s) => stages[s.id]?.status === "PROVEN").length;

// ── blockers, each stating WHOSE move it is ─────────────────────────────────────────────────────
const record = loadEplGradedRecord();
const blockers = [];
if (!record || record.team.matches < 20) {
  blockers.push({ id: "calibration-sample", state: "REALITY_GATED", detail: `calibration needs a preregistered backtest against settled results and ${record?.team.matches ?? 0} match(es) have been graded. No amount of engineering shortens this; matches have to be played.` });
}
if (stages.data?.status !== "PROVEN") {
  const cold = (forecasts?.rows ?? []).filter((r) => r.coldStart?.home || r.coldStart?.away).length;
  blockers.push({ id: "cold-start-clubs", state: "REALITY_GATED", detail: `newly promoted clubs have no top-flight history and run at the league-average baseline; ${cold} fixture(s) in the current forecast set are flagged coldStart. Clears as those clubs accumulate real matches — never by widening what "covered" means.` });
}
if (stages.schedule?.status !== "PROVEN") {
  blockers.push({ id: "postponement-lineage", state: "REALITY_GATED", detail: "the schedule stage wants a postponement handled end to end, and the season has not supplied one." });
}
/*
 * THE PRODUCT LANE, DERIVED FROM THE GATE THAT ACTUALLY DECIDES IT.
 *
 * This was a hard-coded FOUNDER_ACTION saying the decision had not been taken. It has been, and a
 * hard-coded blocker would have gone on asserting otherwise — the same shape as the track-record
 * sentence a settler was quietly invalidating. So the state is read from lab-eligibility, which
 * computes it from artifacts on disk every run and closes the lane again by itself if the prices go
 * stale or the slate empties. A blocker appears only when the lane is genuinely shut.
 */
const lane = (() => {
  try {
    const all = labEligibility(path.join(APP, "public", "data"), NOW.slice(0, 10), NOW);
    const me = all.find((x) => x.id === "epl") ?? null;
    return me ? { live: me.live, blocked: me.blocked ?? null } : null;
  } catch { return null; }
})();
if (lane == null) {
  blockers.push({ id: "product-lane-unknown", state: "ENGINEERING", detail: "the Lab eligibility gate could not be evaluated, so this lane's state is unknown — which is not the same as closed." });
} else if (!lane.live) {
  blockers.push({ id: "product-lane-closed", state: "REALITY_GATED", detail: `the Lab gate has closed this lane: ${lane.blocked}. It reopens by itself when the evidence returns.` });
}
/*
 * ALERTING IS CHECKED WHERE IT IS ACTUALLY CHECKABLE.
 *
 * This read process.env.OPS_WEBHOOK_URL and reported the secret unset. A local script cannot see a
 * GitHub repository secret, so that check could only ever return "unset" — it was reporting an
 * inability to look as a fact about the world, which is the same defect as the page that claimed no
 * match had been graded because it could not read a file. The secret has been set since
 * 2026-07-31, and delivery is proven: an ops-alert-test dispatch emitted neither the "unset" notice
 * nor the delivery-failure warning, the only two ways ops_alert.sh reports a problem.
 *
 * What IS checkable from here is the wiring: does this sport's workflow pass the secret to the
 * alert script at all? A secret that exists and is never referenced alerts nobody.
 */
const alerting = (() => {
  const wired = ["epl-matchweek.yml", "epl-settle.yml"].filter((w) => {
    const src = readText(path.join(ROOT, ".github", "workflows", w));
    return src && /OPS_WEBHOOK_URL/.test(src) && /ops_alert\.sh/.test(src);
  });
  return { wired, all: wired.length === 2 };
})();
if (!alerting.all) {
  blockers.push({
    id: "ops-alerting-unwired",
    state: "ENGINEERING",
    detail: `an EPL workflow does not pass OPS_WEBHOOK_URL to scripts/ops_alert.sh, so its failures reach the Actions tab only (wired: ${alerting.wired.join(", ") || "none"}).`,
  });
}

const out = {
  schemaVersion: 1,
  artifact: "epl-lane-status",
  dataClass: "INTERNAL_ADMIN",
  generatedAt: NOW,
  nextCluster,
  freshness: {
    fixtures: freshnessOf("fixtures", fixtureCapture, ["capturedAt", "generatedAt"]),
    odds: freshnessOf("odds", odds, ["capturedAt", "generatedAt"]),
    forecasts: freshnessOf("forecasts", forecasts, ["generatedAt"]),
    playerProjections: freshnessOf("player projections", players, ["generatedAt"]),
    results: freshnessOf("results", results, ["generatedAt", "sourceAsOf"]),
  },
  cadence: { lineupCoverage: coverage, budget },
  forecastSet: forecasts
    ? { generatedAt: forecasts.generatedAt, counts: forecasts.counts ?? null, rows: (forecasts.rows ?? []).length }
    : UNKNOWN("no forecast artifact"),
  playerSet: players
    ? { generatedAt: players.generatedAt, validation: players.validation?.state ?? null, counts: players.counts ?? null, markets: (players.markets ?? []).map((m) => m.id) }
    : UNKNOWN("no player projection artifact"),
  record: record
    ? { sampleState: record.sampleState, matches: record.team.matches, hits: record.team.hits, meanLogLoss: record.team.meanLogLoss, playerRows: record.player.rows, playerVoided: record.player.voided }
    : UNKNOWN("no graded ledger could be read"),
  gate: { maturity, proven, of: GATE_STAGES.length, remaining: remainingPath(stages, SPORT_ASSESSMENTS.epl).map((r) => ({ stage: r.stage, status: r.status, requiredProof: r.requiredProof })) },
  alerting,
  productLane: lane,
  blockers,
};

const dir = path.join(APP, "public/data/admin");
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "epl-lane.json"), `${JSON.stringify(out, null, 2)}\n`);

console.log(`epl lane: ${maturity} · ${proven}/${GATE_STAGES.length} stages proven · ${blockers.length} blocker(s)`);
console.log(`  next cluster: ${nextCluster.kickoffUtc ?? "—"}${nextCluster.hoursAway != null ? ` (${nextCluster.hoursAway}h, ${nextCluster.fixtures} match(es))` : ""}`);
console.log(`  lineup coverage: ${coverage.state}${coverage.clusters != null ? ` · ${coverage.covered}/${coverage.clusters} clusters, ${coverage.uncoveredMatches} uncovered match(es)` : ""}`);
console.log(`  credits: ${budget.state}${budget.projectedTotal != null ? ` · ${budget.projectedTotal}/${budget.ceiling} projected, headroom ${budget.headroom}` : ""}`);
console.log(`  record: ${record ? `${record.team.matches} match(es) graded, ${record.player.rows} player row(s)` : "unreadable"}`);
for (const b of blockers) console.log(`  blocker ${b.state.padEnd(14)} ${b.id}`);
